#!/usr/bin/env node
import vm from 'node:vm';import {readFileSync,writeFileSync} from 'node:fs';import {fileURLToPath} from 'node:url';import {buildNativeBundle} from '../../../scripts/native-core-bundle.mjs';
if(process.versions.node.split('.')[0]!=='22')throw new Error('Native keyboard oracle requires Node22');
const fixture=fileURLToPath(new URL('./native-keyboard.leaf.jsonl',import.meta.url));const context=vm.createContext({});vm.runInContext(await buildNativeBundle(),context);
const calls=[['nativeInit',[4,{series:[{id:'price',type:'candles',panel:'price'},{id:'volume',type:'histogram',panel:'price',source:'volume'}]}]],['nativeDataExploration',['read']],['nativeDataExploration',['setActive',true]],['nativeDataExploration',['navigate','Home']],['nativeDataExploration',['read']],['nativeDataExploration',['navigate','ArrowDown']],['nativeDataExploration',['read']],['nativeDataExploration',['navigate','End']],['nativeCommand',['removeSeries',['volume']]],['nativeDataExploration',['refresh']],['nativeDataExploration',['read']],['nativeDataExploration',['setActive',false]],['nativeDataExploration',['navigate','Home']],['nativeDataExploration',['unknown']],['nativeDataExploration',['read',false]]];
const rows=calls.map(([name,args])=>{try{return{name,args,result:vm.runInContext(`${name}(...JSON.parse(${JSON.stringify(JSON.stringify(args))}))`,context)};}catch(e){return{name,args,error:{name:e.name,message:e.message}};}});
const output=[{kind:'header',schema:'barochart.native-keyboard',version:1,node:process.version},...rows].map(v=>JSON.stringify(v)).join('\n')+'\n';if(process.argv[2]==='--write'){writeFileSync(fixture,output);console.log('native keyboard source calls',rows.length);}else if(process.argv[2]==='--check'){if(readFileSync(fixture,'utf8')!==output)throw new Error('keyboard fixture stale');console.log('native keyboard oracle fresh',rows.length);}else process.stdout.write(output);
